$mdPaths = @('TASK.md','docs/evidence/T-001/README.md','docs/evidence/T-001/FOLLOW_UP_DRAFT.md')
foreach ($mdPath in $mdPaths) {
    $lines = [System.IO.File]::ReadAllLines((Join-Path (Get-Location) $mdPath))
    $columns = 0
    for ($i = 0; $i -lt $lines.Count; $i++) {
        $line = $lines[$i]
        if ($line.StartsWith('|')) {
            $n = [regex]::Matches($line, '(?<!\\)\|').Count - 1
            if ($columns -eq 0) { $columns = $n }
            if ($n -ne $columns) { throw ('Table mismatch: ' + $mdPath + ':' + ($i + 1)) }
        } else { $columns = 0 }
        if ([regex]::Matches($line, '`').Count % 2 -ne 0 -or $line -match '[ \t]+$') { throw ('Markdown delimiter/whitespace: ' + $mdPath + ':' + ($i + 1)) }
    }
}
Write-Output 'Markdown table/code/whitespace checks passed'
